import{_ as e,o as a,c as t,aa as d}from"./chunks/framework.BAs_AphD.js";const n="/buildary-help-preview/academy/img/zalozeni-obdobi/04.webp",s="/buildary-help-preview/academy/img/zalozeni-obdobi/06.webp",h=JSON.parse('{"title":"Období soupisů","description":"","frontmatter":{"title":"Období soupisů","wiki":"cs:performedworks:period"},"headers":[],"relativePath":"performedworks/period.md","filePath":"performedworks/period.md","lastUpdated":1794209661000}'),r={name:"performedworks/period.md"};function i(b,o,l,p,m,u){return a(),t("div",null,[...o[0]||(o[0]=[d('<h1 id="obdobi-soupisu" tabindex="-1">Období soupisů <a class="header-anchor" href="#obdobi-soupisu" aria-label="Permalink to &quot;Období soupisů&quot;">​</a></h1><p>Soupisy provedených prací se zadávají vždy za období, obvykle za kalendářní měsíc. Období zakládá administrátor stavby a platí pro všechny soupisy na stavbě – zhotovitele i podzhotovitelů.</p><p>Krok za krokem: <a href="/buildary-help-preview/akademie/zalozeni-obdobi">Založit období soupisu</a> v Akademii.</p><h2 id="kdo-obdobi-zaklada" tabindex="-1">Kdo období zakládá <a class="header-anchor" href="#kdo-obdobi-zaklada" aria-label="Permalink to &quot;Kdo období zakládá&quot;">​</a></h2><p>Založit nové období nebo změnit existující smí jen uživatel s kompetencí <strong>Administrace stavby</strong> – viz <a href="/buildary-help-preview/performedworks/competences">Kompetence pro soupisy</a>.</p><p>Období je společné pro celou stavbu. Je jedno, jestli ho založíte v okně <strong>SPP Zhotovitele</strong>, nebo <strong>SPP Podzhotovitele</strong> – objeví se v obou.</p><h2 id="zalozit-obdobi" tabindex="-1">Založit období <a class="header-anchor" href="#zalozit-obdobi" aria-label="Permalink to &quot;Založit období&quot;">​</a></h2><ol><li>V okně <strong>SPP Zhotovitele</strong> nebo <strong>SPP Podzhotovitele</strong> klikněte v záhlaví na ikonu kalendáře vedle názvu období. Otevře se okno <strong>Výběr období</strong>. Pokud na stavbě zatím žádné období není, okno se otevře samo s upozorněním, že je potřeba nejprve založit první období.</li><li>Klikněte na <strong>Přidat období</strong>.</li><li>Vyplňte formulář <strong>Vytvoření období</strong> a potvrďte <strong>OK</strong>.</li></ol><figure class="shot" style="--w:760px;"><img src="'+n+'" alt="Formulář Vytvoření období s poli Období od, Období do a Popis období" loading="lazy"></figure><table tabindex="0"><thead><tr><th>Pole</th><th>Význam</th></tr></thead><tbody><tr><td><strong>Období od</strong></td><td>První den období.</td></tr><tr><td><strong>Období do</strong></td><td>Poslední den období. Po vyplnění začátku se doplní samo, ale můžete ho změnit na jakékoli jiné datum.</td></tr><tr><td><strong>Popis období</strong></td><td>Vytvoří se z obou dat, například 1.10.2026 - 31.10.2026. Můžete ho přepsat třeba na Říjen 2026.</td></tr></tbody></table><p>Po založení období dostanou e-mail všichni, kdo smějí zadávat soupisy za zhotovitele nebo podzhotovitele a mají e-mailová oznámení o soupisech zapnutá – viz <a href="/buildary-help-preview/performedworks/competences#e-mailova-oznameni">E-mailová oznámení</a>.</p><h2 id="seznam-obdobi" tabindex="-1">Seznam období <a class="header-anchor" href="#seznam-obdobi" aria-label="Permalink to &quot;Seznam období&quot;">​</a></h2><p>V okně <strong>Výběr období</strong> jsou všechna období stavby se sloupci <strong>Období</strong>, <strong>Popis období</strong>, <strong>Období od</strong>, <strong>Období do</strong> a <strong>Stav</strong>. Nové období má stav <strong>Nezahájeno</strong>. Kliknutím na období ho otevřete v okně soupisu. Ikony na konci řádku slouží k úpravě a smazání období.</p><figure class="shot" style="--w:760px;"><img src="'+s+'" alt="Okno Výběr období se založeným obdobím Říjen 2026 ve stavu Nezahájeno" loading="lazy"></figure><div class="tip custom-block"><p class="custom-block-title">Období a napojené aplikace</p><p>Délku období si zvolíte libovolně. Je-li ale stavba napojená na jinou aplikaci, respektujte její pravidla – například v RSV nesmí období přesáhnout hranici jednoho měsíce. Napojené aplikace popisuje <a href="/buildary-help-preview/performedworks/budget#odkud-rozpocet-nacist">Načíst rozpočet</a>.</p></div>',15)])])}const c=e(r,[["render",i]]);export{h as __pageData,c as default};
